const PROCESS_SUMMARY_LINE_LIMIT: usize = 3;
const PROCESS_SUMMARY_CHAR_LIMIT: usize = 600;
const PROCESS_SUMMARY_HIGH_SIGNAL_MARKERS: [&str; 5] = [
    "error:",
